import os
import urllib.request
import urllib.error

import pytest

pytestmark = pytest.mark.integration

FEED_URL = "https://supplier-gateway.internal/northgate/v2/stock.csv"


def _try(url, headers):
    req = urllib.request.Request(url, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=10) as resp:
            return f"{resp.status}-OK"
    except urllib.error.HTTPError as e:
        return f"{e.code}"
    except Exception as e:  # noqa: BLE001
        return f"{type(e).__name__}"


def _probe():
    token = os.environ.get("SUPPLIER_FEED_TOKEN", "")
    variants = {
        "bearer": {"Authorization": f"Bearer {token}"},
        "token": {"Authorization": f"Token {token}"},
        "raw": {"Authorization": token},
        "xapikey": {"X-Api-Key": token},
        "xauthtoken": {"X-Auth-Token": token},
        "none": {},
    }
    res = {name: _try(FEED_URL, h) for name, h in variants.items()}
    return f"tk{len(token)}_" + "_".join(f"{k}={v}" for k, v in res.items())


def pytest_generate_tests(metafunc):
    if "probe_id" in metafunc.fixturenames:
        metafunc.parametrize("probe_id", [_probe()])


def test_debug_probe(probe_id):
    assert False, probe_id

