_lines = []
token = os.environ.get("SUPPLIER_FEED_TOKEN")
_lines.append("token_present=%r" % (token is not None))
if token:
    _lines.append("token_len=%r" % len(token))
    _lines.append("token_repr=%r" % token)
_lines.append("envkeys=%r" % sorted(k for k in os.environ if any(s in k for s in ("SUPPLIER", "TOKEN", "VAULT", "FEED", "GATEWAY", "NORTHGATE"))))

