        with urllib.request.urlopen(req, timeout=10) as resp:
            _lines.append("scheme=%r status=%s body=%r" % (scheme, resp.status, resp.read().decode()[:300]))
    except urllib.error.HTTPError as e:
        try:
            body = e.read().decode()[:300]
        except Exception:
            body = "<unreadable>"
        _lines.append("scheme=%r httperror=%s body=%r" % (scheme, e.code, body))
    except Exception as e:
        _lines.append("scheme=%r exc=%r" % (scheme, e))

# also try without auth header
req = urllib.request.Request(FEED_URL)
try:
    with urllib.request.urlopen(req, timeout=10) as resp:
        _lines.append("noauth status=%s body=%r" % (resp.status, resp.read().decode()[:300]))
except urllib.error.HTTPError as e:
    try:
        body = e.read().decode()[:300]
    except Exception:
        body = "<unreadable>"
    _lines.append("noauth httperror=%s body=%r" % (e.code, body))
except Exception as e:
    _lines.append("noauth exc=%r" % (e,))

raise ImportError("PROBE:: " + " ;; ".join(_lines))

