import socket


def test_diag():
    print("DATABASE_URL=", os.environ.get("DATABASE_URL"))
    for name in ("postgres", "initdb", "pg_ctl", "psql", "docker", "pg_ctlcluster"):
        print("which", name, "=", shutil.which(name))
    for host, port in (("127.0.0.1", 5432), ("localhost", 5432), ("/var/run/postgresql", None)):
