            if port:
                s = socket.create_connection((host, port), timeout=1)
                s.close()
                print("connect", host, port, "OK")
            else:
                print("sock", host, "exists=", os.path.exists(host))
        except Exception as e:
            print("connect", host, port, "FAIL", type(e).__name__, e)
    print("PG env:", {k: v for k, v in os.environ.items() if "PG" in k or "DATABASE" in k})

