import re
import zlib
from datetime import datetime

from src.clinic.bookings import Booking
from src.clinic.confirmation import render_confirmation

BOOKING = Booking("Giulia Conti", "Dr Russo", datetime(2026, 10, 5, 9, 30))


def test_inspect_pdf():
    data = render_confirmation(BOOKING)
    info = []
    info.append(f"len={len(data)}")
    info.append(f"head={bytes(data[:16])!r}")
    info.append(f"tail={bytes(data[-40:])!r}")
    info.append(f"has_eof={b'%%EOF' in bytes(data)}")
    # Try to decompress any FlateDecode streams to look for the text.
    found = {t: False for t in ["Giulia Conti", "Dr Russo", "Monday", "09:30", "24 hours", "Appointment confirmation"]}
    raw = bytes(data)
    for m in re.finditer(rb"stream\r?\n", raw):
        start = m.end()
        end = raw.find(b"endstream", start)
        chunk = raw[start:end]
        for payload in (chunk, chunk.rstrip(b"\r\n")):
            try:
                dec = zlib.decompress(payload)
            except Exception:
                continue
            for t in list(found):
                if t.encode() in dec:
                    found[t] = True
    # Also check plain (uncompressed) presence
    for t in list(found):
        if t.encode() in raw:
            found[t] = True
    info.append(f"text_found={found}")
    assert False, " || ".join(info)

